SELECT 

WHERE 1 = 1

    AND task.task_no LIKE CONCAT('%', #{taskNo}, '%')


    AND meter.meter_no LIKE CONCAT('%', #{meterNo}, '%')


    AND image.uploader_type = #{uploaderType}


    AND image.uploader_id = #{uploaderId}


    AND image.image_status = #{imageStatus}


    AND image.storage_status = #{storageStatus}


    AND result_image.result_id IS NOT NULL


    AND result_image.result_id IS NULL


    AND image.deleted = #{deleted}


    AND image.created_at >= #{createdAtStart}


    AND image.created_at <= #{createdAtEnd}

ORDER BY image.created_at DESC, image.id DESC

SELECT image.* FROM meter_image AS image WHERE image.id IN
#{imageId}
ORDER BY image.id FOR UPDATE

SELECT image.*
FROM meter_image AS image
INNER JOIN meter_reading_task AS task
        ON task.id = image.task_id
LEFT JOIN meter_reading_result_image AS relation
       ON relation.image_id = image.id
WHERE image.storage_status IN ('STORED', 'DELETE_PENDING')
  AND (
      image.storage_status = 'DELETE_PENDING'
      OR (
          image.updated_at <= #{cutoff}
          AND (image.deleted = 1 OR image.image_status = 'INVALID')
      )
      OR (
          image.created_at <= #{cutoff}
          AND relation.image_id IS NULL
          AND task.task_status IN (
              'PENDING_REVIEW', 'COMPLETED', 'FAILED', 'CANCELLED'
          )
      )
  )
ORDER BY image.updated_at ASC, image.id ASC
LIMIT #{limit}
